  Core:      { pt: "Core",      es: "Core",            fr: "Core",          de: "Core",       en: "Core"       },
  "Antebraço": { pt: "Antebraço", es: "Antebrazo",    fr: "Avant-bras",    de: "Unterarme",  en: "Forearms"   },
