export function getEquipmentLabel(equipment: string, locale: AppLocale = getStoredLocale()): string {
  const normalized = equipment
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .trim();
  const entry = equipmentLabels[normalized];
  if (entry) return entry[locale] ?? entry.pt;
  return equipment;
}
